2: import { useId } from "react";
3: import {
4:   toggleQuickHelpCardExpanded,
5:   useQuickHelpCardExpanded,
6: } from "../../hooks/useQuickHelpCardExpanded";
7: import type { ReactNode } from "react";
8: import "./styles.css";
9: 
10: type QuickHelpCardProps = {
11:   renderSlot?: (name: string, fallback?: ReactNode) => ReactNode;
12: };
13: 
14: const messages: Record<string, { title: string; expand: string; collapse: string }> = {
15:   "zh-CN": { title: "使用帮助", expand: "展开", collapse: "折叠" },
16:   "en-US": { title: "Usage Help", expand: "Expand", collapse: "Collapse" },
17: };
18: 
19: export function QuickHelpCardPlugin(props: QuickHelpCardProps) {
20:   const localeCode = useAgentUILocaleCode();
21:   const text = messages[localeCode] ?? messages["zh-CN"]!;
22:   // Shared with header actions such as the "知道了" action, so both plugins
23:   // control the same expansion state and it survives theme switching.
24:   const expanded = useQuickHelpCardExpanded();
25:   const bodyId = useId();
26: 
27:   const headerActions = props.renderSlot ? props.renderSlot("headerActions", null) : null;
28:   const body = props.renderSlot ? props.renderSlot("body", null) : null;
29:   // Action buttons grow independently of the help text, so the row is its own slot.
30:   const footerActions = props.renderSlot ? props.renderSlot("footerActions", null) : null;
31: 
32:   return (
33:     <section className="quick-help-card" aria-label={text.title}>
34:       <div className="quick-help-card__header">
35:         <button
36:           type="button"
37:           className="quick-help-card__toggle"
38:           aria-expanded={expanded}
39:           aria-controls={bodyId}
40:           onClick={toggleQuickHelpCardExpanded}
41:         >
42:           <span className="quick-help-card__title">{text.title}</span>
43:           <span className="quick-help-card__indicator" aria-hidden="true">
44:             {expanded ? "▾" : "▸"}
45:           </span>
46:           <span className="quick-help-card__toggle-label">
47:             {expanded ? text.collapse : text.expand}
48:           </span>
49:         </button>
50:         {headerActions ? (
51:           <div className="quick-help-card__header-actions">{headerActions}</div>
52:         ) : null}
53:       </div>
54:       <div className="quick-help-card__body" id={bodyId} hidden={!expanded}>
55:         {body}
56:       </div>
57:       {footerActions ? (
58:         <div className="quick-help-card__footer" hidden={!expanded}>
59:           {footerActions}
60:         </div>
61:       ) : null}
62:     </section>
63:   );
64: }
